actionCenter.handClickTitle:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { isEmpty, openConfirmBox } = globalUtils
  const titleVal = eventParams.params.val.title
  if(titleVal === "S 参数"){
    dataCenter.showOtherPlot.SParameter = !dataCenter.showOtherPlot.SParameter
    return
  }
  if(titleVal === "阻抗"){
    dataCenter.showOtherPlot.Impedance = !dataCenter.showOtherPlot.Impedance
    return
  }
  if(dataCenter.useCenerate){
    openConfirmBox({
        title: '提示',
        message: "有任务正在生成中..."
    })
    return
  }
  const activateText = eventParams.params?.activateText
  if(isEmpty(activateText)) return
  const AntennaNamelist = actionCenter.defaultParams("AntennaName")
  const BackingNameList = actionCenter.defaultParams("BackingName")
  const ArrayNameList = actionCenter.defaultParams("ArrayName")
  if(ArrayNameList.includes(activateText)){
    dataCenter.tabName.ArrayName = activateText
    return
  }
  if(AntennaNamelist.includes(activateText)){
    dataCenter.tabName.AntennaName = activateText
    return
  }
  if(BackingNameList.includes(activateText)){
    dataCenter.tabName.BackingName = activateText
    return
  }
}

