actionCenter.generate:
async ({dataCenter, actionCenter, globalUtils}, eventParams) => {
   dataCenter.showLoading = true
   dataCenter.allMessage = '计算中...'
   const { post, getFilePath, isEmpty} = globalUtils
   // const {returnData} = globalUtils
   let { tabName, frequency, frequencyRenge, frequencyRangeUnit, DipoleFm, FoldedFm, VeeFm, MeanderFm, Rectangular, Circular, Corner, RectangularArr, Linear } = dataCenter
   // 新设计使用默认值
   if(!isEmpty(eventParams.params)){
     const defParams = eventParams.params[0]
     if(tabName.BackingName === "None"){
       frequency = defParams.frequency
       frequencyRenge = defParams.frequencyRenge
       frequencyRangeUnit = defParams.frequencyRangeUnit
       if(defParams?.DipoleFm){
         DipoleFm = defParams?.DipoleFm
       }
       if(defParams?.FoldedFm){
         FoldedFm = defParams?.FoldedFm
       }
       if(defParams?.VeeFm){
         VeeFm = defParams?.VeeFm
       }
       if(defParams?.MeanderFm){
        MeanderFm = defParams?.MeanderFm
       }
     }
     if(tabName.BackingName !== "None"){
       frequency = defParams[tabName.AntennaName].frequency
       frequencyRenge = defParams[tabName.AntennaName].frequencyRenge
       frequencyRangeUnit = defParams[tabName.AntennaName].frequencyRangeUnit
       if(defParams[tabName.AntennaName]?.DipoleFm){
         DipoleFm = defParams[tabName.AntennaName]?.DipoleFm
       }
       if(defParams[tabName.AntennaName]?.FoldedFm){
         FoldedFm = defParams[tabName.AntennaName]?.FoldedFm
       }
       if(defParams[tabName.AntennaName]?.VeeFm){
         VeeFm = defParams[tabName.AntennaName]?.VeeFm
       }
       if(defParams[tabName.AntennaName]?.MeanderFm){
        MeanderFm = defParams[tabName.AntennaName]?.MeanderFm
       }
       if(tabName.BackingName === "Rectangular"){
         Rectangular = defParams
       }
       if(tabName.BackingName === "Circular"){
          Circular = defParams
       }
       if(tabName.BackingName === "Corner"){
         Corner = defParams
       }
     }
     if(tabName.ArrayName === "Linear"){
        Linear = actionCenter.defaultParams("Linear")
     }
     if(tabName.ArrayName === "RectangularArr"){
        RectangularArr = actionCenter.defaultParams("RectangularArr")
     }
   }
   let code = ``
   let returnCode = ``
   let BackingCode = ``
   let AntennaCode = ``
   let BackingPrefix = ``
   let showPlotCode = ``
   let ArrayCode = ``
   if(tabName.BackingName !== 'None'){
     BackingPrefix = `.Exciter`
   }
   switch (tabName.ArrayName) {
        case 'RectangularArr':
            ArrayCode = `
              antennaObject = rectangularArray()
              antennaObject.Size = ${RectangularArr.Size}
              antennaObject.RowSpacing = ${RectangularArr.RowSpacing}
              antennaObject.ColumnSpacing = ${RectangularArr.ColumnSpacing}
              antennaObject.Lattice = "${RectangularArr.Lattice}"  # "Triangular"
              antennaObject.AmplitudeTaper = ${RectangularArr.AmplitudeTaper}
              antennaObject.PhaseShift = ${RectangularArr.PhaseShift}
              antennaObject.Tilt = ${RectangularArr.Tilt}
              antennaObject.TiltAxis = ${RectangularArr.TiltAxis}
            `
            break;
        case 'Linear':
            ArrayCode = `
              antennaObject = linearArray()
              antennaObject.NumElements = ${Linear.NumElements}
              antennaObject.ElementSpacing = ${Linear.ElementSpacing}
              antennaObject.AmplitudeTaper = ${Linear.AmplitudeTaper}
              antennaObject.PhaseShift = ${Linear.PhaseShift}
              antennaObject.Tilt = ${Linear.Tilt}
              antennaObject.TiltAxis = ${Linear.TiltAxis}
            `
            break;
        default:
            break;
    }
   switch (tabName.BackingName) {
        case 'None':
            break;
        case 'Rectangular':
            const { reflectorFm, substrateFm } = Rectangular
            BackingCode = `
              Element1 = reflector()
              # Adjust backing structure dimensions
              antennaObject.Element.GroundPlaneLength = ${reflectorFm.GroundPlaneLength}
              antennaObject.Element.GroundPlaneWidth = ${reflectorFm.GroundPlaneWidth}
              antennaObject.Element.Spacing = ${reflectorFm.Spacing}
              antennaObject.Element.EnableProbeFeed = ${reflectorFm.EnableProbeFeed}
              antennaObject.Element.Tilt = ${reflectorFm.Tilt}
              antennaObject.Element.TiltAxis = ${reflectorFm.TiltAxis}
              # Update substrate properties 
              antennaObject.Element.Substrate.Name = "${substrateFm.Name}"
              antennaObject.Element.Substrate.EpsilonR = ${substrateFm.EpsilonR}
              antennaObject.Element.Substrate.LossTangent = ${substrateFm.LossTangent}
              antennaObject.Element.Substrate.Thickness = ${substrateFm.Thickness}
            `
            break;
        case 'Circular':
            const { reflectorFmCir, substrateFmCir } = Circular
            BackingCode = `
              Element1 = reflectorCircular()
              # Adjust backing structure dimensions
              antennaObject.Element.GroundPlaneRadius = ${reflectorFmCir.GroundPlaneRadius}
              antennaObject.Element.Spacing = ${reflectorFmCir.Spacing}
              antennaObject.Element.EnableProbeFeed = ${reflectorFmCir.EnableProbeFeed}
              antennaObject.Element.Tilt = ${reflectorFmCir.Tilt}
              antennaObject.Element.TiltAxis = ${reflectorFmCir.TiltAxis}
              # Update substrate properties 
              antennaObject.Element.Substrate.Name = "${substrateFmCir.Name}"
              antennaObject.Element.Substrate.EpsilonR = ${substrateFmCir.EpsilonR}
              antennaObject.Element.Substrate.LossTangent = ${substrateFmCir.LossTangent}
              antennaObject.Element.Substrate.Thickness = ${substrateFmCir.Thickness}
            `
            break;
        case 'Corner':
            const { reflectorFmCor } = Corner
            BackingCode = `
              Element1 = reflectorCorner()
              # Adjust backing structure dimensions
              antennaObject.Element.GroundPlaneLength = ${reflectorFmCor.GroundPlaneLength}
              antennaObject.Element.GroundPlaneWidth = ${reflectorFmCor.GroundPlaneWidth}
              antennaObject.Element.CornerAngle = ${reflectorFmCor.CornerAngle}
              antennaObject.Element.Spacing = ${reflectorFmCor.Spacing}
              antennaObject.Element.Tilt = ${reflectorFmCor.Tilt}
              antennaObject.Element.TiltAxis = ${reflectorFmCor.TiltAxis}
            `
            break;
        default:
            break;
    }
   switch (tabName.AntennaName) {
          case 'Dipole':
              AntennaCode = `
                ${ArrayCode}
                ${BackingCode}
                Element1${BackingPrefix} = dipole()
                antennaObject.Element = Element1
                antennaObject.Element${BackingPrefix}.Length = ${DipoleFm.Length}
                antennaObject.Element${BackingPrefix}.Width = ${DipoleFm.Width}
                antennaObject.Element${BackingPrefix}.FeedOffset = ${DipoleFm.FeedOffset}
                antennaObject.Element${BackingPrefix}.Tilt = ${DipoleFm.Tilt}
                antennaObject.Element${BackingPrefix}.TiltAxis = ${DipoleFm.TiltAxis}
              `
              break;
          case 'Folded':
              AntennaCode = `
                ${ArrayCode}
                ${BackingCode}
                Element1${BackingPrefix} = dipoleFolded()
                antennaObject.Element = Element1
                antennaObject.Element${BackingPrefix}.Length = ${FoldedFm.Length}
                antennaObject.Element${BackingPrefix}.Width = ${FoldedFm.Width}
                antennaObject.Element${BackingPrefix}.Spacing = ${FoldedFm.Spacing}
                antennaObject.Element${BackingPrefix}.Tilt = ${FoldedFm.Tilt}
                antennaObject.Element${BackingPrefix}.TiltAxis = ${FoldedFm.TiltAxis}
              `
              break;
          case 'Vee':
              AntennaCode = `
                ${ArrayCode}
                ${BackingCode}
                Element1${BackingPrefix} = dipoleVee()
                antennaObject.Element = Element1
                antennaObject.Element${BackingPrefix}.ArmLength = ${VeeFm.ArmLength}
                antennaObject.Element${BackingPrefix}.Width = ${VeeFm.Width}
                antennaObject.Element${BackingPrefix}.ArmElevation = ${VeeFm.ArmElevation}
                antennaObject.Element${BackingPrefix}.Tilt = ${VeeFm.Tilt}
                antennaObject.Element${BackingPrefix}.TiltAxis = ${VeeFm.TiltAxis}
              `
              break;
          case 'Meander':
              AntennaCode = `
                ${ArrayCode}
                ${BackingCode}
                Element1${BackingPrefix} = dipoleMeander()
                antennaObject.Element = Element1
                antennaObject.Element${BackingPrefix}.ArmLength = ${MeanderFm.ArmLength}
                antennaObject.Element${BackingPrefix}.Width = ${MeanderFm.Width}
                antennaObject.Element${BackingPrefix}.NotchLength = ${MeanderFm.NotchLength}
                antennaObject.Element${BackingPrefix}.NotchWidth = ${MeanderFm.NotchWidth}
                antennaObject.Element${BackingPrefix}.Tilt = ${MeanderFm.Tilt}
                antennaObject.Element${BackingPrefix}.TiltAxis = ${MeanderFm.TiltAxis}
              `
              break;
          default:
              break;
    }
   // 组织配置代码
   if(true){
     const freqRange = {"Hz": 1, "kHz": 1e3, "MHz": 1e6, "GHz": 1e9, "THz": 1e12 }[frequencyRangeUnit]
     code = `
       ${AntennaCode}
       freqRange = collect(${frequencyRenge}) * ${freqRange}
     `
   }
   // 组织绘图代码
   if(true){
     let show = `
       enable_show(false)
       show(antennaObject)
       SNRfig = gcf()
       SNRfig_io = IOBuffer()
       SNRfig.savefig(SNRfig_io)
       plt_close()
       showfig_base64 = Base64.base64encode(take!(SNRfig_io))
       showfig_base64 = replace(showfig_base64, "\\n" => "")
       enable_show(true)
     `
     let impedance = `
       enable_show(false)
       impedance(antennaObject, freqRange)
       Pdfig = gcf()
       Pdfig_io = IOBuffer()
       Pdfig.savefig(Pdfig_io)
       plt_close()
       impfig_base64 = Base64.base64encode(take!(Pdfig_io))
       impfig_base64 = replace(impfig_base64, "\\n" => "")
       enable_show(true)
     `
     let SParameter = `
       enable_show(false)
       RefImpedance = ${frequency}
       sparameters(antennaObject, freqRange, RefImpedance);
       Envfig = gcf()
       Envfig_io = IOBuffer()
       Envfig.savefig(Envfig_io)
       plt_close()
       SPfig_base64 = Base64.base64encode(take!(Envfig_io))
       SPfig_base64 = replace(SPfig_base64, "\\n" => "")
       enable_show(true)
     `
     showPlotCode = `
       ${show}
       ${impedance}
       ${SParameter}
     `
   }
   // 导出的代码
   if(true){
      returnCode =  `
         ret = Dict(
           "show_base64" => showfig_base64,
           "impedance_base64" => impfig_base64, 
           "SParameter_base64" => SPfig_base64
      ) `
    }
   // 组装最后的代码
   const lastCode = `
        arrayObject = ""
        let 
           ${code}
           global arrayObject  = antennaObject
           ${showPlotCode}
           ${returnCode}
           using JSON
           output_text = JSON.json(ret)
           io = open("${getFilePath()}","w")
           write(io,output_text)
           close(io)
        end`
     console.log("lastCode:", lastCode )
     let message = await post({
        key: "generate", 
        command: "excute", 
        code: lastCode,
      })
     // const retureRes = message.data?.value ?? returnData
     const retureRes = message.data?.value
     console.log("generateRes", retureRes )
     if(retureRes){
        dataCenter.show_base64 = retureRes.show_base64
        dataCenter.impedance_base64 = retureRes.impedance_base64
        dataCenter.SParameter_base64 = retureRes.SParameter_base64
        dataCenter.showLoading = false
        dataCenter.allMessage = "就绪"
        dataCenter.useCenerate = false
        dataCenter.disableApply = true
        return
     }
    dataCenter.useCenerate = false
    dataCenter.showLoading = false
    dataCenter.disableApply = false
    dataCenter.allMessage = "计算出错，请稍后尝试..."
}

actionCenter.apply:
async ({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { showNewDesign, tabName:{ AntennaName, BackingName, ArrayName}, disableApply} = dataCenter
  if(disableApply) return
  dataCenter.useCenerate = true
  if(!showNewDesign){
    await actionCenter.generate()
    return
  }
  const reqParams = actionCenter.defaultParams(`${ArrayName}${AntennaName}${BackingName}`)
  await actionCenter.generate(reqParams)
}

