actionCenter.watchApplyBtn:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { isEmpty } = globalUtils
  const { showNewDesign, tabName:{ AntennaName, BackingName, ArrayName }} = dataCenter
  if(showNewDesign) return
  if(isEmpty(dataCenter.noNewDesign)) return
  console.log("watchApplyBtn", eventParams, dataCenter.noNewDesign)
  let propertyName = eventParams.property[0]
  let newVal = eventParams.value
  const BackingNameList = actionCenter.defaultParams("BackingName")
  const ArrayNameList = actionCenter.defaultParams("ArrayName")
  if(BackingNameList.includes(propertyName)){
    dataCenter.disableApply = (JSON.stringify(newVal) === JSON.stringify(dataCenter.noNewDesign.BackingParams))
    return
  }
  if(ArrayNameList.includes(propertyName)){
    dataCenter.disableApply = (JSON.stringify(newVal) === JSON.stringify(dataCenter.noNewDesign.ArrayParams))
    return
  }
  dataCenter.disableApply = (JSON.stringify(newVal) === JSON.stringify(dataCenter.noNewDesign.AntennaParams))
}

actionCenter.valChangeInput:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  console.log("valChangeInput", eventParams)
  const { isEmpty } = globalUtils
  let newVal = eventParams.newValue
  let oldVal = eventParams.oldValue
  let propertyName = eventParams.property[0]
  if(isEmpty(newVal)){
    if(!isEmpty(oldVal)){
      dataCenter[propertyName] = oldVal
    }
    return
  }
  if(isEmpty(dataCenter.noNewDesign)) return
  dataCenter.disableApply = (newVal == dataCenter.noNewDesign[propertyName])
}
